use sqlx::{MySql,Pool};use uuid::Uuid;pub async fn run(pool:&Pool<MySql>)->anyhow::Result<()> {let (count,):(i64,)=sqlx::query_as("SELECT COUNT(*) as count FROM users").fetch_one(pool).await?;if count==0{let now=chrono::Utc::now().naive_utc();for (n,e) in [("Alice","alice@example.com"),("Bob","bob@example.com"),("Carol","carol@example.com")]{sqlx::query("INSERT INTO users (id,name,email,created_at,updated_at) VALUES (?,?,?,?,?)").bind(Uuid::new_v4()).bind(n).bind(e).bind(now).bind(now).execute(pool).await?;}log::info!("Seeded users");}else{log::info!("Users exist; skipping seed");}Ok(())}